<script>
(()=>{const key='giftcheta:favorites:v1';let renderVersion=0;function clean(item){if(!item||!Number.isSafeInteger(Number(item.id))||Number(item.id)<1||typeof item.slug!=='string'||!/^[a-z0-9_-]+$/i.test(item.slug)||typeof item.name!=='string')return null;return{id:Number(item.id),slug:item.slug,name:item.name.slice(0,240),image:typeof item.image==='string'&&/^\/(?:uploads|assets)\/[a-z0-9_./-]+$/i.test(item.image)?item.image:null,price:Number.isFinite(Number(item.price))?Number(item.price):0}}function read(){try{const parsed=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(parsed)?parsed.map(clean).filter(Boolean).slice(0,100):[]}catch{return[]}}function paintButtons(items=read()){const ids=new Set(items.map(item=>item.id));document.querySelectorAll('[data-favorite-count]').forEach(badge=>{badge.textContent=String(items.length);badge.hidden=items.length===0});document.querySelectorAll('.store-favorites-link').forEach(link=>link.setAttribute('aria-label',`Любими продукти, ${items.length}`));document.querySelectorAll('[data-favorite-toggle]').forEach(button=>{let item=null;try{item=clean(JSON.parse(button.dataset.favoriteProduct||'null'))}catch{}const selected=!!item&&ids.has(item.id);button.setAttribute('aria-pressed',String(selected));button.setAttribute('aria-label',selected?'Премахни продукта от любими':'Добави продукта в любими')})}function save(items){try{localStorage.setItem(key,JSON.stringify(items));paintButtons(items);window.dispatchEvent(new CustomEvent('giftcheta:favorites-changed',{detail:{items}}))}catch{}}function toggle(item){const product=clean(item);if(!product)return false;const items=read(),existing=items.some(value=>value.id===product.id);save(existing?items.filter(value=>value.id!==product.id):[product,...items].slice(0,100));return!existing}async function render(items=read()){const page=document.querySelector('[data-favorites-page]'),grid=page?.querySelector('[data-favorites-grid]'),empty=page?.querySelector('[data-favorites-empty]');if(!grid||!empty)return;const version=++renderVersion;grid.hidden=items.length===0;empty.hidden=items.length!==0;if(!items.length){grid.replaceChildren();window.dispatchEvent(new CustomEvent('giftcheta:favorites-rendered',{detail:{count:0}}));return}try{const response=await fetch(`/favorites/products?ids=${items.map(item=>item.id).join(',')}`,{credentials:'same-origin',headers:{Accept:'text/html'}});if(!response.ok)throw new Error('Favorites could not be loaded');const html=await response.text();if(version!==renderVersion)return;const template=document.createElement('template');template.innerHTML=html;const cards=[...template.content.children],visibleIds=new Set(cards.map(card=>{try{return Number(JSON.parse(card.querySelector('[data-favorite-toggle]')?.dataset.favoriteProduct||'null')?.id)||0}catch{return 0}}).filter(Boolean)),visibleItems=items.filter(item=>visibleIds.has(item.id));if(visibleItems.length!==items.length){try{localStorage.setItem(key,JSON.stringify(visibleItems))}catch{}paintButtons(visibleItems)}grid.replaceChildren(...cards);paintButtons(visibleItems);grid.hidden=grid.childElementCount===0;empty.hidden=grid.childElementCount!==0;window.dispatchEvent(new CustomEvent('giftcheta:favorites-rendered',{detail:{count:grid.childElementCount}}))}catch{if(version===renderVersion){grid.replaceChildren();grid.hidden=true;empty.hidden=false;window.dispatchEvent(new CustomEvent('giftcheta:favorites-rendered',{detail:{count:0}}))}}}window.GiftchetaFavorites={read,toggle,refresh:()=>render(),sync:()=>paintButtons()};document.addEventListener('click',event=>{const button=event.target.closest('[data-favorite-toggle]');if(!button)return;event.preventDefault();let product=null;try{product=JSON.parse(button.dataset.favoriteProduct||'null')}catch{}const selected=toggle(product);paintButtons();if(selected){button.classList.remove('is-animating');void button.offsetWidth;button.classList.add('is-animating');window.setTimeout(()=>button.classList.remove('is-animating'),650)}});window.addEventListener('giftcheta:favorites-changed',event=>render(event.detail?.items));window.addEventListener('storage',event=>{if(event.key===key){paintButtons();render()}});window.addEventListener('giftcheta:navigated',()=>paintButtons());window.addEventListener('giftcheta:catalog-updated',()=>paintButtons());paintButtons();render()})();
</script>
<script>(()=>{const banner=document.querySelector('[data-announcement-shipping]');if(!banner)return;const threshold=Number(banner.dataset.thresholdCents||0),money=new Intl.NumberFormat('bg-BG',{style:'currency',currency:'EUR'});let previous=Number(banner.dataset.subtotalCents||0);function update(cart){const spent=Math.max(0,Number(cart?.subtotal_cents)||0),remaining=Math.max(0,threshold-spent),progress=threshold>0?Math.min(100,Math.round(spent/threshold*100)):100;banner.dataset.subtotalCents=String(spent);banner.querySelector('[data-cart-remaining]').textContent=remaining>0?'Остават ': 'Поздравления! Вие се възползвахте от безплатна доставка.';banner.querySelector('[data-cart-remaining-amount]').textContent=remaining>0?money.format(remaining/100):'';banner.querySelector('[data-cart-remaining-suffix]').textContent=remaining>0?'до безплатна доставка':'';banner.querySelector('[data-cart-progress-fill]').style.width=progress+'%';banner.querySelector('[role="progressbar"]').setAttribute('aria-valuenow',String(progress));banner.classList.toggle('is-reached',remaining===0);banner.classList.toggle('is-empty',spent===0);if(spent>previous){banner.classList.remove('is-progressing');void banner.offsetWidth;banner.classList.add('is-progressing');window.setTimeout(()=>banner.classList.remove('is-progressing'),1250)}previous=spent}window.addEventListener('cart:updated',event=>update(event.detail));})();</script>
<script>
