function sync(cart){const items=cart?.items||[],rows=new Map([...list.querySelectorAll('.cart-drawer-item')].map(row=>[row.dataset.itemKey,row]));if(!items.length||items.some(item=>!rows.has(item.item_key))){render(cart);return}cartState=cart;updateCounts(cartState);for(const item of items){const row=rows.get(item.item_key);row.querySelector('.cart-drawer-quantity span').textContent=String(item.quantity);row.querySelector('.cart-drawer-quantity [data-drawer-delta="1"]').disabled=Number(item.quantity)>=999;row.querySelector('.cart-drawer-price').textContent=money.format((Number(item.line_total_cents)||0)/100);row.removeAttribute('aria-busy');delete row.dataset.pending;rows.delete(item.item_key)}for(const row of rows.values())row.remove()}
