<script>
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-grid-cart-add]');if(!form)return;event.preventDefault();if(form.dataset.pending==='1')return;form.dataset.pending='1';const button=form.querySelector('button[type="submit"]'),label=button?.querySelector('.product-card-add-label'),feedback=form.querySelector('.product-card-add-feedback'),original=label?.textContent||'';if(button){button.disabled=true;button.classList.remove('is-success');button.classList.add('is-loading');button.setAttribute('aria-busy','true')}if(label)label.textContent='Добавя се…';if(feedback){feedback.hidden=true;feedback.textContent=''}let succeeded=false;try{const response=await fetch(form.action,{method:'POST',body:new FormData(form),credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-Token':form.querySelector('[name="_csrf"]')?.value||''}}),payload=await response.json();if(!response.ok)throw new Error(payload?.error?.message||'Продуктът не беше добавен.');const cart=payload.data.cart,badge=document.querySelector('[data-cart-count]'),count=Number(cart?.count||0);if(badge){badge.textContent=String(count);badge.closest('.cart-link')?.setAttribute('aria-label','Количка, '+count+' продукта');badge.classList.remove('is-bumping');void badge.offsetWidth;badge.classList.add('is-bumping')}window.dispatchEvent(new CustomEvent('cart:updated',{detail:cart}));if(button){button.classList.remove('is-loading');button.classList.add('is-success')}if(label)label.textContent='Добавено';succeeded=true;window.setTimeout(()=>window.dispatchEvent(new CustomEvent('cart:open',{detail:cart})),500);window.setTimeout(()=>{if(button)button.classList.remove('is-success');if(label)label.textContent=original},1500)}catch(error){if(feedback){feedback.textContent=error instanceof Error?error.message:'Възникна грешка. Опитайте отново.';feedback.hidden=false}}finally{if(button){button.classList.remove('is-loading');button.removeAttribute('aria-busy');window.setTimeout(()=>{but