<script>
(()=>{document.addEventListener('submit',event=>{if(event.defaultPrevented)return;const form=event.target;if(!(form instanceof HTMLFormElement))return;const button=event.submitter instanceof HTMLButtonElement?event.submitter:form.querySelector('button[type="submit"],button:not([type])');if(!(button instanceof HTMLButtonElement)||!button.classList.contains('button'))return;if(form.dataset.storeSubmitting==='1'){event.preventDefault();return}form.dataset.storeSubmitting='1';button.disabled=true;button.classList.add('store-action-pending');button.setAttribute('aria-busy','true')});document.addEventListener('click',event=>{if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const link=event.target.closest('a.button,a.cart-summary-continue');if(!link||link.target||link.hasAttribute('download'))return;if(link.matches('.cart-checkout-button,.cart-summary-continue')){if(link.getAttribute('aria-disabled')==='true'){event.preventDefault();return}link.setAttribute('aria-disabled','true');link.setAttribute('aria-busy','true');link.setAttribute('tabindex','-1');const arrow=link.querySelector('[data-cart-checkout-arrow],[data-cart-continue-arrow]');arrow?.setAttribute('hidden','');const spinner=link.querySelector('[data-cart-checkout-spinner],[data-cart-continue-spinner]');if(spinner)spinner.hidden=false;return}link.classList.add('store-action-pending');link.setAttribute('aria-busy','true')},true)})();
</script>
<script>
(()=>{const skeleton='<div class="product-loading-breadcrumb" aria-hidden="true"></div><div class="product-page-loading" role="status" aria-label="Зареждаме продукта"><div class="product-loading-gallery" aria-hidden="true"><div class="product-loading-stage"></div><div class="product-loading-thumbs"><i class="product-loading-thumb"></i><i class="product-loading-thumb"></i><i class="product-loading-thumb"></i><i class="product-loading-thumb"></i><i class="product-loading-thumb"></i></div></div><div class="product-loading-info" aria-hidden="true"><i class="product-loading-block is-title"></i><i class="product-loading-block is-short"></i><i class="product-loading-block is-description"></i><i class="product-loading-block is-description"></i><i class="product-loading-block is-status"></i><i class="product-loading-block is-price"></i><i class="product-loading-block is-options"></i><i class="product-loading-block is-button"></i></div></div>';document.addEventListener('click',event=>{if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const link=event.target.closest('a[href]');if(!link||link.target||link.hasAttribute('download')||link.closest('.quick-view-dialog'))return;const url=new URL(link.href,location.href);if(url.origin!==location.origin||!/^\/product\/[a-z0-9_-]+\/?$/i.test(url.pathname)||(url.pathname===location.pathname&&url.search===location.search))return;const current=document.querySelector('main.shell.main');if(!current)return;const loading=document.createElement('main');loading.className='shell main product-navigation-loading';loading.setAttribute('aria-busy','true');loading.innerHTML=skeleton;current.replaceWith(loading);window.scrollTo({top:0,behavior:'instant'})},true)})();
</script>
<script>
(()=>{const skeleton='<div class="category-loading-heading category-loading-shape" aria-hidden="true"></div><div class="category-loading-layout"><aside class="category-loading-sidebar" aria-hidden="true"><i class="category-loading-shape is-title"></i><i class="category-loading-shape is-field"></i><i class="category-loading-shape"></i><i class="category-loading-shape"></i><i class="category-loading-shape is-title"></i><i class="category-loading-shape"></i><i class="category-loading-shape"></i></aside><section><div class="category-loading-toolbar"><i class="category-loading-shape"></i><i class="category-loading-shape"></i></div><div class="category-loading-grid" aria-hidden="true">'+Array.from({length:8},()=>'<article class="category-loading-card"><div class="category-loading-media"></div><div class="category-loading-info"><i class="category-loading-shape"></i><i class="category-loading-shape" style="width:62%"></i><i class="category-loading-shape" style="width:40%"></i></div></article>').join('')+'</div></section></div>';document.addEventListener('click',event=>{if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;const link=event.target.closest('a[href]');if(!link||!link.closest('.store-nav')||link.target||link.hasAttribute('download'))return;const url=new URL(link.href,location.href);if(url.origin!==location.origin||!(url.pathname==='/products'||/^\/category\/[a-z0-9_-]+\/?$/i.test(url.pathname))||(url.pathname===location.pathname&&url.search===location.search))return;const current=document.querySelector('main.shell.main');if(!current)return;const loading=document.createElement('main');loading.className='shell main category-navigation-loading';loading.setAttribute('aria-busy','true');loading.innerHTML=skeleton;current.replaceWith(loading);window.scrollTo({top:0,behavior:'instant'})},true)})();
