<script>
(()=>{if(window.__giftchetaSsrNavigation)return;window.__giftchetaSsrNavigation=true;let activeController=null;const mainSelector='main.shell.main';function normalizedPath(path){return new URL(path,location.href).pathname.replace(/\/+$/,'')||'/'}function syncActiveNav(path=location.pathname){const nav=document.querySelector('[data-category-scroller]');if(!nav)return;const navRoot=nav.parentElement;const links=[...(navRoot?.querySelectorAll('a[href]')||[])];const target=normalizedPath(path);links.forEach(link=>{link.classList.remove('is-active');link.removeAttribute('aria-current')});if(target==='/products'){const allProducts=nav.querySelector(':scope > a[href="/products"]');allProducts?.classList.add('is-active');allProducts?.setAttribute('aria-current','page');return}const topMatch=[...nav.querySelectorAll(':scope > a[href^="/category/"]')].find(link=>normalizedPath(link.href)===target);if(topMatch){topMatch.classList.add('is-active');if(!topMatch.hasAttribute('data-category-trigger'))topMatch.setAttribute('aria-current','page');const menuId=topMatch.getAttribute('aria-controls');const menu=menuId?navRoot?.querySelector(`#${menuId}`):null;const allInCategory=menu?.querySelector('.store-nav-menu-all');if(allInCategory&&normalizedPath(allInCategory.href)===target){allInCategory.classList.add('is-active');allInCategory.setAttribute('aria-current','page')}return}const childMatch=links.find(link=>link.closest('[data-category-menu]')&&normalizedPath(link.href)===target);if(childMatch){const menu=childMatch.closest('[data-category-menu]');nav.querySelector(`[aria-controls="${menu.id}"]`)?.classList.add('is-active');childMatch.classList.add('is-active');childMatch.setAttribute('aria-current','page')}}syncActiveNav();function eligible(link,event){if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||link.target||link.hasAttribute('download'))return false;const url=new URL(link.href,location.href);return url.origin===location.origin&&!url.pathname.startsWith('/admin')&&!url.pathname.startsWith('/api/')&&!url.pathname.startsWith('/cart/files/')&&url.pathname!=='/sitemap.xml'&&url.pathname!=='/robots.txt'}function setMeta(name,content,property=false){const selector=property?`meta[property="${name}"]`:`meta[name="${name}"]`;let item=document.head.querySelector(selector);if(!item){item=document.createElement('meta');item.setAttribute(property?'property':'name',name);document.head.append(item)}item.content=content||''}window.giftchetaNavigate=async function(href,{historyMode='push',scroll=true}={}){const url=new URL(href,location.href);if(url.origin!==location.origin)return;activeController?.abort();const controller=new AbortController();activeController=controller;document.documentElement.classList.add('is-navigating');try{const response=await fetch(url.href,{credentials:'same-origin',signal:controller.signal,headers:{Accept:'application/vnd.giftcheta.fragment+html'}});if(!response.ok||!response.headers.get('X-Page-Title')){location.href=url.href;return}const markup=await response.text(),template=document.createElement('template');template.innerHTML=markup;const next=template.content.querySelector(mainSelector),current=document.querySelector(mainSelector);if(!next||!current){location.href=url.href;return}const schema=next.dataset.pageSchema?decodeURIComponent(escape(atob(next.dataset.pageSchema))):'';current.replaceWith(next);const pageTitle=decodeURIComponent(response.headers.get('X-Page-Title')||'Giftcheta'),pageDescription=decodeURIComponent(response.headers.get('X-Page-Description')||''),pageCanonical=decodeURIComponent(response.headers.get('X-Page-Canonical')||'');document.title=`${pageTitle} | Giftcheta`;setMeta('description',pageDescription);setMeta('robots',response.headers.get('X-Page-Robots'));const canonical=pageCanonical;let canonicalLink=document.head.querySelector('link[rel="canonical"]');if(canonical){if(!canonicalLink){canonicalLink=document.createElement('link');canonicalLink.rel='canonical';document.head.append(canonicalLink)}canonicalLink.href=canonical}else canonicalLink?.remove();setMeta('og:title',pageTitle,true);setMeta('og:description',pageDescription,true);setMeta('og:url',canonical||url.href,true);document.head.querySelectorAll('script[type="application/ld+json"][data-page-schema]').forEach(node=>node.remove());if(schema){const node=document.createElement('script');node.type='application/ld+json';node.dataset.pageSchema='';node.textContent=schema;document.head.append(node)}if(historyMode==='push')history.pushState({giftcheta:true},'',url.href);else if(historyMode==='replace')history.replaceState({giftcheta:true},'',url.href);syncActiveNav(url.pathname);for(const oldScript of [...next.querySelectorAll('script')]){if(oldScript.type==='application/ld+json')continue;const script=document.createElement('script');for(const attr of oldScript.attributes)script.setAttribute(attr.name,attr.value);script.textContent=oldScript.textContent;oldScript.replaceWith(script)}window.GiftchetaFavorites?.refresh();window.GiftchetaFavorites?.sync();window.dispatchEvent(new CustomEvent('giftcheta:navigated',{detail:{url:url.href}}));if(scroll){if(url.hash){requestAnimationFrame(()=>document.getElementById(decodeURIComponent(url.hash.slice(1)))?.scrollIntoView({behavior:'smooth'}))}else window.scrollTo({top:0,behavior:'instant'})}}catch(error){if(error.name!=='AbortError')location.href=url.href}finally{if(activeController===controller){activeController=null;document.documentElement.classList.remove('is-navigating')}}};document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(!link||!eligible(link,event))return;const url=new URL(link.href,location.href);if(url.pathname===location.pathname&&url.search===location.search&&url.hash){return}event.preventDefault();window.giftchetaNavigate(url.href)});document.addEventListener('submit',event=>{const form=event.target;if(event.defaultPrevented||!(form instanceof HTMLFormElement)||(form.method||'get').toLowerCase()!=='get'||form.target||form.matches('[data-live-catalog-filters]'))return;const url=new URL(form.action||location.href,location.href);url.search=new URLSearchParams(new FormData(form)).toString();event.preventDefault();window.giftchetaNavigate(url.href)});window.addEventListener('popstate',()=>{syncActiveNav();window.giftchetaNavigate(location.href,{historyMode:'none',scroll:true})});})();
</script>
<script>
(()=>{const form=document.querySelector('[data-product-search]');if(!form)return;const input=form.querySelector('input[name="q"]'),list=form.querySelector('#store-search-suggestions');if(!input||!list)return;let timer=null,controller=null,activeIndex=-1,requestId=0;const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');activeIndex=-1;controller?.abort();requestId++};const price=value=>{const amount=Number(value);return Number.isFinite(amount)?new Intl.NumberFormat('bg-BG',{style:'currency',currency:'EUR'}).format(amount):''};const node=(tag,className,text)=>{const element=document.createElement(tag);if(className)element.className=className;if(text)element.textContent=text;return element};function render(items,query){list.replaceChildren();activeIndex=-1;list.append(node('div','store-search-suggestions-heading',query.trim().length<2?'Наскоро добавени':'Предложения'));if(!items.length){list.append(node('div','store-search-suggestions-empty',query.trim().length<2?'Все още няма нови продукти.':'Не открихме продукти по това търсене.'));list.hidden=false;input.setAttribute('aria-expanded','true');return}items.forEach(item=>{const link=node('a','store-search-suggestion');link.href='/product/'+encodeURIComponent(item.slug);link.setAttribute('role','option');link.setAttribute('aria-selected','false');link.dataset.searchOption='';const image=item.image?node('img','store-search-suggestion-image'):node('span','store-search-suggestion-image is-empty');if(item.image){image.src='/'+item.image;image.alt=item.image_alt||'';image.loading='lazy';image.decoding='async'}const copy=node('span','store-search-suggestion-copy');copy.append(node('span','store-search-suggestion-name',item.name));if(item.description)copy.append(node('span','store-search-suggestion-description',item.description));const priceWrap=node('span','store-search-suggestion-price');priceWrap.append(node('span','',price(item.price)));if(Number(item.regular_price)>Number(item.price))priceWrap.append(node('del','',price(item.regular_price)));link.append(image,copy,priceWrap);list.append(link)});const footer=node('a','store-search-suggestions-footer',query.trim().length<2?'Виж всички продукти':'Виж всички резултати за „'+query.trim()+'“');footer.href=query.trim().length<2?'/products?sort=latest':'/search?q='+encodeURIComponent(query.trim());list.append(footer);list.hidden=false;input.setAttribute('aria-expanded','true')}async function search(){const query=input.value.trim(),id=++requestId;controller?.abort();controller=new AbortController();list.replaceChildren(node('div','store-search-suggestions-loading','Търсим подходящи продукти…'));list.hidden=false;input.setAttribute('aria-expanded','true');try{const response=await fetch('/api/v1/search/suggestions?q='+encodeURIComponent(query),{credentials:'same-origin',signal:controller.signal,headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Search suggestions unavailable');const payload=await response.json();if(id===requestId)render(Array.isArray(payload?.data?.items)?payload.data.items:[],query)}catch(error){if(error.name!=='AbortError'&&id===requestId)close()}}input.addEventListener('focus',()=>{clearTimeout(timer);search()});input.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(search,180)});input.addEventListener('keydown',event=>{const options=[...list.querySelectorAll('[data-search-option]')];if(event.key==='Escape'){close();return}if(event.key==='ArrowDown'||event.key==='ArrowUp'){if(list.hidden){search();return}if(!options.length)return;event.preventDefault();activeIndex=(activeIndex+(event.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((option,index)=>option.setAttribute('aria-selected',String(index===activeIndex)));const active=options[activeIndex];if(active){input.setAttribute('aria-activedescendant','search-suggestion-'+activeIndex);active.id='search-suggestion-'+activeIndex;active.scrollIntoView({block:'nearest'})}return}if(event.key==='Enter'&&!list.hidden&&activeIndex>=0&&options[activeIndex]){event.preventDefault();options[activeIndex].click()}});form.addEventListener('submit',()=>{clearTimeout(timer);close()});document.addEventListener('pointerdown',event=>{if(!form.contains(event.target))close()});document.addEventListener('click',event=>{if(event.target.closest('[data-search-option]'))close()});window.addEventListener('pagehide',()=>{controller?.abort();clearTimeout(timer)})})();
</script>
